  "literacy.tutorial.step2Title": "2. ഓട്ടോമാറ്റിക് AI സ്റ്റുഡിയോ ഫോട്ടോകൾ",
  "literacy.tutorial.step2Desc": "സാധാരണ ഫോണിൽ ഫോട്ടോ എടുക്കുക. AI പശ്ചാത്തലം മാറ്റി മനോഹരമാക്കും.",
  "literacy.tutorial.step3Title": "3. ന്യായവില നിർണ്ണയ ഉപദേശം",
  "literacy.tutorial.step3Desc": "അസംസ്‌കൃത വസ്തുക്കളും നിങ്ങളുടെ അധ്വാനവും കണക്കാക്കി ന്യായവില നിശ്ചയിക്കുന്നു.",
  "literacy.tutorial.step4Title": "4. ബാങ്ക് അക്കൗണ്ടിലേക്ക് നേരിട്ട് പണം (DBT)",
