  "privacy.kicker": "DPDP ആക്റ്റ് 2023 നിയമപരമായ അനുസരണം",
  "privacy.title": "സ്വകാര്യതാ നയം",
  "privacy.lastUpdated": "അവസാനം അപ്ഡേറ്റ് ചെയ്തത്: സെപ്റ്റംബർ 2026 • ഇന്ത്യാ ഗവൺമെൻ്റ് നാഷണൽ ഡിജിറ്റൽ ഇൻഫ്രാസ്ട്രക്ചർ",
  "privacy.section1.heading": "1. നിയമപരമായ പ്രതിബദ്ധതയും വ്യാപ്തിയും",
  "privacy.section2.heading": "2. ഞങ്ങൾ ശേഖരിക്കുന്ന ഡാറ്റ (ഡാറ്റ മിനിമൈസേഷൻ്റെ തത്വം)",
  "privacy.section3.heading": "3. പ്രോസസ്സിംഗിൻ്റെയും നേരിട്ടുള്ള പേഔട്ടുകളുടെയും ഉദ്ദേശം",
  "privacy.section3.intro": "ശേഖരിച്ച ഡാറ്റ ഇനിപ്പറയുന്ന വ്യക്തമായ ഉദ്ദേശ്യങ്ങൾക്കായി മാത്രം പ്രോസസ്സ് ചെയ്യുന്നു:",
  "privacy.section3.bullet1": "0% പ്ലാറ്റ്‌ഫോം കിഴിവുകളോടെ ആർട്ടിസാൻ ഗിൽഡുകളിലേക്ക് നേരിട്ടുള്ള ഡിബിടി ബാങ്ക് പേയ്‌മെൻ്റുകൾ സുഗമമാക്കുന്നു.",
  "privacy.section3.bullet2": "ടാംപർ പ്രൂഫ് ക്രിപ്‌റ്റോഗ്രാഫിക് Ed25519 ഡിജിറ്റൽ പ്രൊവെനൻസ് സർട്ടിഫിക്കറ്റുകൾ മിണ്ടിംഗ്.",
  "privacy.section3.bullet4": "SMS, ഇമെയിൽ വഴിയുള്ള നിവൃത്തിയും ഡെലിവറി സ്റ്റാറ്റസ് അറിയിപ്പുകളും ഉറപ്പാക്കുന്നു.",
  "privacy.section4.heading": "4. മൂന്നാം കക്ഷി ഡാറ്റ വിൽപ്പനയ്ക്ക് സമ്പൂർണ്ണ നിരോധനം",
  "privacy.section5.heading": "5. ക്രിപ്‌റ്റോഗ്രാഫിക് സെക്യൂരിറ്റി & കുക്കി പോളിസി",
  "privacy.section6.heading": "6. ഡാറ്റ വിഷയ അവകാശങ്ങളും പരാതി പരിഹാരവും",
