  "terms.title": "സേവന നിബന്ധനകൾ",
  "terms.lastUpdated": "അവസാനം അപ്ഡേറ്റ് ചെയ്തത്: സെപ്റ്റംബർ 2026 • സാമൂഹിക നീതി & ശാക്തീകരണ മന്ത്രാലയം, ഇന്ത്യാ ഗവൺമെൻ്റ്",
  "terms.section1.heading": "1. പ്ലാറ്റ്‌ഫോം മാൻഡേറ്റും പൊതു അടിസ്ഥാന സൗകര്യങ്ങളും",
  "terms.section2.heading": "2. ഭൂമിശാസ്ത്രപരമായ സൂചനകൾ (GI) & ആധികാരികത നിലവാരം",
  "terms.section3.heading": "3. 100% നേരിട്ടുള്ള പേഔട്ടുകളും 0% പ്ലാറ്റ്‌ഫോം കിഴിവുകളും",
  "terms.section4.heading": "4. ഓർഡർ-ടു-ഓർഡർ & സ്ഥാപനപരമായ പൂർത്തീകരണം",
  "terms.section5.heading": "5. പരമ്പരാഗത സാംസ്കാരിക പ്രകടനങ്ങളുടെ ബൗദ്ധിക സ്വത്ത്",
  "terms.section6.heading": "6. തർക്ക പരിഹാരവും അധികാരപരിധിയും",
